    void rec::deleteSmall(golang::internal::runtime::maps::Map* m, abi::MapType* typ, uintptr_t hash, gocpp::unsafe_pointer key)
    {
        auto g = gocpp::Init<groupReference>([=](auto& x) {
            x.data = m->dirPtr;
        });

        auto match = rec::matchH2(gocpp::recv(rec::ctrls(gocpp::recv(g))), h2(hash));

        for(; match != 0; )
        {
            auto i = rec::first(gocpp::recv(match));
            auto slotKey = rec::key(gocpp::recv(g), typ, i);
            auto origSlotKey = slotKey;
            if(rec::IndirectKey(gocpp::recv(typ)))
            {
                slotKey = *((gocpp::unsafe_pointer*)(slotKey));
            }
            if(typ->Key->Equal(key, slotKey))
            {
                m->used--;

                if(rec::IndirectKey(gocpp::recv(typ)))
                {
                    // Clearing the pointer is sufficient.
                    *(gocpp::unsafe_pointer*)(origSlotKey) = nullptr;
                }
                else
                if(rec::Pointers(gocpp::recv(typ->Key)))
                {
                    // Only bother clearing if there are pointers.
                    typedmemclr(typ->Key, slotKey);
                }

                auto slotElem = rec::elem(gocpp::recv(g), typ, i);
                if(rec::IndirectElem(gocpp::recv(typ)))
                {
                    // Clearing the pointer is sufficient.
                    *(gocpp::unsafe_pointer*)(slotElem) = nullptr;
                }
                else
                {
                    // Unlike keys, always clear the elem (even if
                    // it contains no pointers), as compound
                    // assignment operations depend on cleared
                    // deleted values. See
                    // https://go.dev/issue/25936.
                    typedmemclr(typ->Elem, slotElem);
                }

                // We only have 1 group, so it is OK to immediately
                // reuse deleted slots.
                rec::set(gocpp::recv(rec::ctrls(gocpp::recv(g))), i, ctrlEmpty);
                return;
            }
            match = rec::removeFirst(gocpp::recv(match));
        }
    }

